B.atE=new A.a7("Heyy selam! Ben Deli Bekir! Bir kilo domates rica edecektim.","Aaa pardon sen benim kendi manav\u0131m de\u011filmi\u015fsin. Ka\xe7t\u0131m ben!...","Ahh veremezsin tabii, tezgahtaki mallar\u0131n hep \xe7\xfcr\xfck!")
B.at1=new A.a7("Bekir geldi! D\xfcn gece r\xfcyamda buradan uzay meki\u011fi \u0131smarlam\u0131\u015f\u0131m. Haz\u0131r m\u0131?","S\xfcper! Ama ehliyetim trakt\xf6re. Sen kullan, ben el sallar\u0131m!","\u0130yi ki vermedin, otopark\u0131m zaten dolu. U\xe7tum ben!")
B.asP=new A.a7("\u015e\u015f\u015ft! Duvarlar\u0131n\u0131 dinlemeye geldim. F\u0131s\u0131r f\u0131s\u0131r konu\u015fuyorlar da.","Hmm... Bu duvar fa diyez s\xf6yl\xfcyor. Akordu bozuk, ben gittim!","Duvarlar k\xfcst\xfc ama olsun, dedikoduyu kap\u0131dan dinlerim!")
B.at2=new A.a7("Selam! Buzdolab\u0131ma k\u0131\u015fl\u0131k lastik takaca\u011f\u0131m. Sende var m\u0131?","Dur \xf6nce dolab\u0131n ehliyeti var m\u0131 soray\u0131m. Muayenesi de ge\xe7mi\u015f, ka\xe7t\u0131m!","Sen anlamazs\u0131n, benim dolap rallici! V\u0131n v\u0131n!")
B.au5=new A.a7("Kolay gelsin! G\xf6lgemi evde unutmu\u015fum, \xf6d\xfcn\xe7 g\xf6lgen var m\u0131?","Ayy bu g\xf6lge bana b\xfcy\xfck geldi, \xfcst\xfcnden d\xfc\u015ft\xfcm. Al geri, ho\u015f\xe7a kal!","Cimriye bak! G\xfcne\u015f bat\u0131nca bedava al\u0131r\u0131m zaten!")
B.atU=new A.a7("Hey dostum! Denizde bal\u0131klara y\xfczme dersi veriyorum. Bilet al\u0131r m\u0131s\u0131n?","\u0130lk ders bedavaym\u0131\u015f, unutmu\u015fum! Paray\u0131 bal\u0131klar iade edecek, baaay!","Bal\u0131klar bunu duyunca \xe7ok \xfcz\xfclecek. Nefesini tutma da gel!")
B.atV=new A.a7("Selamlar! Bulutlardan bir kilo pamuk \u015feker dev\u015firdim, tartar m\u0131s\u0131n?","Eyvah, terazide eridi! Ya\u011fmur olarak geri \xf6deyece\u011fim, s\xf6z!","Sen bilirsin, ben de hepsini g\xf6kku\u015fa\u011f\u0131na satar\u0131m!")
B.atB=new A.a7("Bekir burada! Kar\u0131ncalar\u0131ma gece lambas\u0131 ar\u0131yorum, minik olsun.","Ah, kar\u0131ncalar tatile \xe7\u0131km\u0131\u015f! Lamba bahara kals\u0131n, ka\xe7t\u0131m!","Karanl\u0131kta kalan kar\u0131ncalar sana mektup yazacak, bilesin!")
B.atd=new A.a7("Merhaba! Saat ka\xe7 diye soracakt\u0131m ama saatim var. Sen niye yoksun?","Do\u011fru cevap! Zaten soruyu ben de anlamam\u0131\u015ft\u0131m. G\xfcle g\xfcle!","Vaktin yokmu\u015f anla\u015f\u0131lan... Benim de saatim var ama vaktim bol!")
B.atQ=new A.a7("Hey! D\xfcn buradan bir kova g\xf6k g\xfcr\xfclt\xfcs\xfc alm\u0131\u015ft\u0131m, garantisi var m\u0131?","Garanti sa\u011folsun ama kova susuyor. \u015eim\u015fe\u011fe \xe7evirdim, \xe7akt\u0131m gittim!","Garantisiz g\xf6k g\xfcr\xfclt\xfcs\xfc m\xfc olur! Ya\u011fmura \u015fikayet edece\u011fim!")
B.ata=new A.a7("Selam kom\u015fu! Papa\u011fan\u0131ma Frans\u0131zca kursu laz\u0131m. Burada m\u0131yd\u0131?","Mersi bokuu! Ama papa\u011fan Almanca konu\u015fmaya ba\u015flam\u0131\u015f bile. Or\xf6vuar!","Papa\u011fan bunu duyarsa senin taklidini yapacak, haberin olsun!")
B.au6=new A.a7("Bekir geldi! R\xfczgara yakalanm\u0131\u015f, sa\xe7lar\u0131m kar\u0131\u015fm\u0131\u015f. Tara\u011f\u0131n var m\u0131?","Of, tarak sa\xe7\u0131m\u0131 tan\u0131mad\u0131! Biz eski dostuz san\u0131yordum. Neyse, u\xe7tum!","R\xfczgarla aran\u0131z bozulacak ama, s\xf6ylemedi deme!")
B.atf=new A.a7("Hi\u015f\u015ft! Ay'a merdiven dayad\u0131m, bir basamak eksik \xe7\u0131kt\u0131. Sende var m\u0131?","Sa\u011f ol! Ama Ay bu gece izinliymi\u015f. Merdiveni y\u0131ld\u0131za dayad\u0131m, t\u0131rmand\u0131m!","Bir basama\u011f\u0131 \xe7ok g\xf6rd\xfcn! Ben de asans\xf6rle \xe7\u0131kar\u0131m!")
B.ath=new A.a7("Selam! Kaplumba\u011fama ko\u015fu ayakkab\u0131s\u0131 bak\u0131yorum, 4 numara.","Ayakkab\u0131lar\u0131 giydi, \u015fimdi de yava\u015f ko\u015fuyor ama \u015eIK ko\u015fuyor! Bay bay!","Kaplumba\u011fa bunu duyunca kabu\u011funa k\xfcsecek, ay\u0131p ettin!")
B.at4=new A.a7("Merhabalar! \xc7oraplar\u0131m\u0131n teki kay\u0131p. Sende mi saklan\u0131yor?","\u0130\u015fte buradaym\u0131\u015f! Ama bu sa\u011f \xe7orap, benim kayb\u0131m soldu. Yine gelirim!","Tamam tamam... \xc7orab\u0131m \xf6zg\xfcrl\xfc\u011f\xfcn\xfc ilan etmi\u015f, sayg\u0131 duyuyorum!")
B.au1=new A.a7("Hey dostum! Sessizlik sat\u0131yor musun? Evdeki \xe7ok g\xfcr\xfclt\xfcl\xfc \xe7\u0131kt\u0131.","\u015e\xfck\xfcr! Ama po\u015fete koyunca konu\u015fmaya ba\u015flad\u0131. \u0130ade ederim sonra!","\u0130yi, ben de g\xfcr\xfclt\xfcy\xfc k\u0131s\u0131k ate\u015fte kaynat\u0131r\u0131m!")
B.asY=new A.a7("Bekir burada! Dolunay\u0131 \xe7eyrek taksitle alabilir miyim?","Anla\u015ft\u0131k! \u0130lk taksit hilal olarak yatt\u0131 bile. Ay sonunda g\xf6r\xfc\u015f\xfcr\xfcz!","Pe\u015fin isteyece\u011fini biliyordum! Y\u0131ld\u0131zlar veresiye veriyor ama!")
B.auB=new A.a7("Selam! Salyangozuma h\u0131z cezas\u0131 kesmi\u015fler. \u0130tiraz dilek\xe7en var m\u0131?","Dilek\xe7e kabul edildi, ceza s\xfcm\xfckl\xfcb\xf6ce\u011fe kesildi! Adalet yerini buldu!","Salyangoz bunu duyunca gaza basacak, sorumluluk sende!")
B.asX=new A.a7("Merhaba! Aynada kendime rastlad\u0131m, \xe7ok benziyoruz. Sence de \xf6yle mi?","De\u011fil mi ama! Yaln\u0131z o benden yak\u0131\u015f\u0131kl\u0131. K\u0131skand\u0131m, gidiyorum!","Sen de mi benzetemedin! O zaman o kimdi?!")
B.auf=new A.a7("Hey! Kar tanelerini sayarken 7'de tak\u0131ld\u0131m. Devam\u0131n\u0131 biliyor musun?","Sekizmi\u015f! Sa\u011f ol, k\u0131\u015f\u0131n kald\u0131\u011f\u0131m yerden devam ederim!","Sayam\u0131yorsan sayma! Ben de ya\u011fmur damlas\u0131na ge\xe7erim, o daha kolay!")
B.aup=new A.a7("Selam dostum! Uykum ka\xe7t\u0131, nereye gitti\u011fini g\xf6rd\xfcn m\xfc?","Demek o tarafa ko\u015ftu! Yast\u0131\u011f\u0131 al\u0131p pe\u015fine d\xfc\u015f\xfcyorum, iyi geceler!","Sende de mi yok! Neyse, kahveyle anla\u015f\u0131r\u0131m ben!")
B.atO=new A.a7("Bekir geldi! Ceketimin d\xfc\u011fmesine konser bileti laz\u0131m, \xf6n s\u0131radan.","Biletler kapal\u0131 gi\u015fe! D\xfc\u011fmem sahnede z\u0131playacak, ben tutamam art\u0131k!","D\xfc\u011fmem \xfcz\xfcnt\xfcden koptu i\u015fte! Mendil de mi yok sende!")
B.auy=new A.a7("Merhaba! Sandalyeme y\xfcr\xfcy\xfc\u015f yapt\u0131r\u0131yorum, tasma satar m\u0131s\u0131n?","Tasmay\u0131 takt\u0131m, sandalye \xf6nde ben arkada! Kim kimi gezdiriyor belli de\u011fil!","Sandalye bunu duyunca d\xf6rt ayak \xfcst\xfcne \xe7\xf6kt\xfc, g\xf6rd\xfcn m\xfc yapt\u0131\u011f\u0131n\u0131!")
B.atA=new A.a7("Hey! G\xf6kku\u015fa\u011f\u0131n\u0131n ucundaki alt\u0131n\u0131 bulan var m\u0131? Kazma getirdim.","Kazma sende kals\u0131n, ben k\xfcre\u011fi kapt\u0131m! Ganimet yar\u0131 yar\u0131ya, ko\u015ftum!","Sen inanmasan da alt\u0131n orada! Ya\u011fmur ya\u011f\u0131nca g\xf6r\xfc\u015f\xfcr\xfcz ortak!")
B.auz=new A.a7("Selam! Esnemem bula\u015f\u0131c\u0131ym\u0131\u015f, maskem d\xfc\u015ft\xfc. Yenisini ver desem?","Ooof \u015fimdi sen de esnedin! G\xf6rd\xfcn m\xfc, maske \u015fart! Ka\xe7t\u0131m eczaneye!","Esnememi tuttum tuttum... Olmad\u0131, sana da bula\u015ft\u0131! \xd6hhaaam!")
B.auc=new A.a7("Bekir burada! Merdivenlerime asans\xf6r dersi veriyorum. Tebe\u015fir var m\u0131?","Tebe\u015firle \xe7izdim, merdiven d\xfcmd\xfcz yoku\u015f oldu! Ders iptal, kayd\u0131m gittim!","Merdivenler s\u0131n\u0131fta kald\u0131 senin y\xfcz\xfcnden! Veli toplant\u0131s\u0131nda konu\u015furuz!")
